export type State =
  | { kind: "loading" }
  | { kind: "ready"; result: string }
  | { kind: "error"; error: string };
export function display(s: State): string {
  switch (s.kind) {
    case "loading": return "Loading";
    case "ready": return s.result;
    case "error": return s.error;
    default: { const exhaustive: never = s; return exhaustive; }
  }
}
export const UserSchema = z.object({ id: z.string(), name: z.string() });
export type User = z.infer<typeof UserSchema>;
export const parseUser = (raw: unknown): User => UserSchema.parse(raw);
export const DurationSchema = z.number().finite().nonnegative();
// Proof assumes the JSON transport represents start as milliseconds since epoch.
// Choose the actual wire format before implementing this parser.
export const TimeRangeSchema = z.object({
  start: z.number().finite().transform(ms => new Date(ms)).pipe(z.date()),
  durationMs: DurationSchema,
}).refine(r => Number.isFinite(new Date(r.start.getTime() + r.durationMs).getTime()),
  { message: "Range end must be a valid date" });
export type TimeRange = z.infer<typeof TimeRangeSchema>;
export const parseTimeRange = (raw: unknown): TimeRange => TimeRangeSchema.parse(raw);
export const sum = (xs: number[]): number => xs.reduce((a, b) => a + b, 0);
export type NonEmpty<T> = [T, ...T[]];
export const choose = (xs: NonEmpty<string>): string =>
  xs[Math.floor(Math.random() * xs.length)] ?? xs[0];
const assert = (ok: boolean, label: string): void => { if (!ok) throw Error(label); };
assert(sum([]) === 0, "empty sum");
assert(choose(["only"]) === "only", "singleton choose");
assert(parseUser({id:"u", name:"Ada"}).name === "Ada", "valid user");
for (const value of [null, {}, {id:42,name:"Ada"}, {id:"u"}]) {
  assert(!UserSchema.safeParse(value).success, "reject invalid user");
}
