  assert(!TimeRangeSchema.safeParse({start:0, durationMs}).success, "reject invalid duration");
}
assert(TimeRangeSchema.safeParse({start:0,durationMs:0}).success, "zero duration");
assert(!TimeRangeSchema.safeParse({start:9e15,durationMs:0}).success, "invalid start");
assert(!TimeRangeSchema.safeParse({start:8.64e15,durationMs:1}).success, "invalid end");
